    status = 'current'
    subtypeSpec = Integer32.subtypeSpec + ConstraintsUnion(SingleValueConstraint(1, 2, 3, 6, 7, 8, 9))
    namedValues = NamedValues(("standalone", 1), ("master", 2), ("extension", 3), ("sat-ethernet", 6), ("sat-tdm", 7), ("primary", 8), ("secondary", 9))

