class TmnxSETSRefQualified(TextualConvention, Integer32):
    description = "The TmnxSETSRefQualified data type is an enumerated integer that\n         describes the values used to identify whether the reference is\n         'qualified' or 'not-qualified' for use by SETS."
    status = 'current'
    subtypeSpec = Integer32.subtypeSpec + ConstraintsUnion(SingleValueConstraint(1, 2))
    namedValues = NamedValues(("qualified", 1), ("not-qualified", 2))

class TmnxSETSRefAlarm(TextualConvention, Bits):
    description = "The TmnxSETSRefAlarm data type is a bitmap that describes the values\n         used to identify the alarms on the SETS timing reference source if the\n         source is 'not-qualified'.\n\n         'los'    - loss of signal\n         'oof'    - out of frequency range\n         'oopir'  - out of pull in range."
    status = 'current'
    namedValues = NamedValues(("los", 0), ("oof", 1), ("oopir", 2))

class TmnxSETSStatus(TextualConvention, Integer32):
    description = 'The TmnxSETSStatus textual convention specifies the status of the\n         Synchronous Timing Equipment Source (SETS).'
