tIPsecIsaMemHighWatermark = NotificationType((1, 3, 6, 1, 4, 1, 6527, 3, 1, 3, 2, 1, 0, 138)).setObjects(("TIMETRA-CHASSIS-MIB", "tmnxMDAHwIndex"))
