tmnxPhysChassPwrSupPemACRect = NotificationType((1, 3, 6, 1, 4, 1, 6527, 3, 1, 3, 2, 1, 0, 144)).setObjects(("TIMETRA-CHASSIS-MIB", "tmnxHwClass"), ("TIMETRA-CHASSIS-MIB", "tmnxPhysChassPowerSupPemACRect"))
